import json,math,pathlib,hashlib
b=pathlib.Path('artifacts/validation/2026-11-01/corner_approach_v1'); run=b/'solo_2p0'; r=json.loads((run/'report.json').read_text()); met=json.loads((b/'solo_2p0_metrics.json').read_text()); surf=json.loads((b/'solo_2p0_surface.json').read_text()); motor=json.loads((b/'solo_2p0_motor_audit.json').read_text()); m=json.loads((b/'solo_2p0_pre_manifest.json').read_text()); fd=json.loads((run/'follow_decisions.jsonl').open().readline())['data']['follow_config']
