 if d.get('truth_longitudinal_mps') is not None and d.get('truth_lateral_mps') is not None:
  lon=float(d['truth_longitudinal_mps']); lat=float(d['truth_lateral_mps']); speeds.append({'trajectory_line':n,'sim_time_s':d.get('sim_time_s'),'truth_longitudinal_mps':lon,'truth_lateral_mps':lat,'ground_speed_mps':math.hypot(lon,lat)})
