result={'profile':r.get('speed_profile'),'passed':r.get('passed'),'command_arguments':m['command_arguments'],'pre_run_manifest':str(b/'solo_2p0_pre_manifest.json'),'input_hash_count':len(m['source_sha256']),'post_run_source_hash_differences':diffs,'report_source_unchanged':r.get('source_unchanged'),'reference_differences_from_corrected_2p0':m['reference_source_hash_differences'],'gear_ratio':m.get('drive_gear_ratio'),'race_path_options':{'g1_race_path':r.get('test_arguments',{}).get('g1_race_path'),'short_boundary_prefix_enabled':fd.get('short_boundary_prefix_enabled'),'parallel_hold_trial':fd.get('parallel_hold_trial'),'pass_release_trial':fd.get('pass_release_trial'),'guard_curve_trial':fd.get('guard_curve_trial'),'traffic_recovery_trial':fd.get('traffic_recovery_trial'),'traffic_path_recovery_trial':fd.get('traffic_path_recovery_trial')},'run':{'progress_m':r.get('progress_m'),'target_progress_m':r.get('target_progress_m'),'completed_laps':r.get('completed_laps'),'lap_length_m':r.get('lap_length_m'),'collision_samples':r.get('collision_samples'),'truth_velocity_sample_count':len(speeds),'peak_truth_ground_speed':peak,'metrics_peak_ground_mps':met.get('peak_ground_mps'),'best_one_second_mean_mps':met.get('best_one_second_mean_mps'),'stop_stable':r.get('stop_stable'),'stop_wait_sim_s':r.get('stop_wait_sim_s'),'stop_displacement_m':r.get('stop_displacement_m'),'stop_collision_samples':r.get('stop_collision_samples'),'dense_pose_stop_evidence':r.get('dense_pose_stop_evidence'),'actuation_stop_ack':r.get('actuation',{}).get('arm_acknowledged'),'final_mcu':r.get('actuation',{}).get('final_mcu'),'gazebo_stop_service':r.get('gazebo_stop_service'),'shutdown_clean':r.get('shutdown_clean'),'process_exit_codes':r.get('process_exit_codes'),'process_errors':r.get('process_errors')},'surface_audit':{'samples':surf.get('samples'),'body_outside_samples':surf.get('body_outside_samples_over_1e-6_m2'),'footprint_outside_samples':surf.get('steering_footprint_outside_samples_over_1e-6_m2'),'wall_wheel_samples':surf.get('wall_wheel_samples'),'max_off_wheels_full':surf.get('interpretations',{}).get('full',{}).get('max_off_wheels'),'penalty_events_full':surf.get('interpretations',{}).get('full',{}).get('penalty_events_merged')},'motor_audit':motor}
out=b/'solo_2p0_final_summary.json'
